using System.Text.RegularExpressions;
using JobOrbit.Application.DTOs.Jobs;
using JobOrbit.Application.DTOs.Matching;
using JobOrbit.Application.Interfaces;
using JobOrbit.Domain.Enums;
using Microsoft.EntityFrameworkCore;

namespace JobOrbit.Infrastructure.Persistence;

public sealed class JobMatchingService(JobOrbitDbContext db,ISystemSettingsProvider settings):IJobMatchingService
{
 sealed record SkillData(string Name,bool Required,decimal? Years);
 sealed record CandidateData(int Id,string? Headline,string? Summary,string? Education,string? Experience,string? Location,List<SkillData> Skills);
 sealed record JobData(int Id,string Title,string Description,string? Requirements,string Location,string? WorkplaceType,string EmploymentType,string? ExperienceLevel,string Organization,string Department,DateTime? ClosingDate,List<SkillData> Skills);
 static readonly Dictionary<string,string> Aliases=new(StringComparer.OrdinalIgnoreCase){{"c sharp","c#"},{"csharp","c#"},{"microsoft sql server","sql server"},{"asp net core","asp.net core"},{"aspnet core","asp.net core"},{"js","javascript"}};
 static readonly HashSet<string> Stop=["junior","senior","lead","developer","engineer","the","and","for","with"];
 public async Task<JobMatchResultDto?>CalculateCandidateJobMatchAsync(int user,int jobId,CancellationToken t=default){var c=await Candidate(user,t);var j=await Job(jobId,true,t);return c is null||j is null?null:Score(c,j);}
 public async Task<IReadOnlyList<JobRecommendationDto>>GetRecommendedJobsAsync(int user,CandidateRecommendationFilter f,CancellationToken t=default)
 {
  f.Limit=Math.Clamp(f.Limit,1,20);if(f.MinimumScore is <0 or >100)throw new ArgumentException("Minimum score must be between 0 and 100.");var c=await Candidate(user,t);if(c is null)return[];var now=DateTime.UtcNow;var q=db.JobPostings.AsNoTracking().Where(x=>x.Status==JobStatus.Published&&(x.ClosingAt==null||x.ClosingAt>now)&&x.Organization.IsActive&&x.Department.IsActive);var rules=(await settings.GetAsync(t)).Recruitment;if(!rules.AllowMultipleApplicationsPerJob)q=q.Where(x=>!x.JobApplications.Any(a=>a.CandidateProfile.UserId==user));if(!string.IsNullOrWhiteSpace(f.Location)){var v=f.Location.Trim();q=q.Where(x=>x.Location.Contains(v));}if(!string.IsNullOrWhiteSpace(f.WorkplaceType)){var v=f.WorkplaceType.Trim();q=q.Where(x=>x.WorkplaceType==v);}if(!string.IsNullOrWhiteSpace(f.EmploymentType)){var v=f.EmploymentType.Trim();q=q.Where(x=>x.EmploymentType==v);}var jobs=await q.OrderByDescending(x=>x.PublishedAt??x.CreatedAt).Take(100).Select(x=>new JobData(x.Id,x.Title,x.Description,x.Requirements,x.Location,x.WorkplaceType,x.EmploymentType,x.ExperienceLevel,x.Organization.Name,x.Department.Name,x.ClosingAt,x.JobSkills.Select(s=>new SkillData(s.Skill.Name,s.IsRequired,s.MinimumYearsOfExperience)).ToList())).ToListAsync(t);return jobs.Select(j=>(j,m:Score(c,j))).Where(x=>!f.MinimumScore.HasValue||x.m.MatchScore>=f.MinimumScore).OrderByDescending(x=>x.m.MatchScore).ThenByDescending(x=>x.m.ConfidenceScore).ThenBy(x=>x.j.ClosingDate).Take(f.Limit).Select(x=>new JobRecommendationDto(x.j.Id,x.j.Title,x.j.Organization,x.j.Department,x.j.Location,x.j.WorkplaceType,x.j.EmploymentType,x.m.MatchScore,x.m.ConfidenceScore,x.m.MatchedSkills,x.m.MissingSkills,x.m.Summary,x.j.ClosingDate)).ToList();
 }
 public async Task<PagedResultDto<RankedCandidateDto>?>GetRankedApplicantsAsync(int recruiter,int jobId,CandidateRankingFilter f,CancellationToken t=default)
 {
  f.Page=Math.Max(1,f.Page);f.PageSize=Math.Clamp(f.PageSize,1,50);if(f.MinimumScore is <0 or >100)throw new ArgumentException("Minimum score must be between 0 and 100.");var job=await db.JobPostings.AsNoTracking().Where(x=>x.Id==jobId&&x.RecruiterProfile.UserId==recruiter).Select(x=>new JobData(x.Id,x.Title,x.Description,x.Requirements,x.Location,x.WorkplaceType,x.EmploymentType,x.ExperienceLevel,x.Organization.Name,x.Department.Name,x.ClosingAt,x.JobSkills.Select(s=>new SkillData(s.Skill.Name,s.IsRequired,s.MinimumYearsOfExperience)).ToList())).SingleOrDefaultAsync(t);if(job is null)return null;var q=db.JobApplications.AsNoTracking().Where(x=>x.JobPostingId==jobId);if(!string.IsNullOrWhiteSpace(f.Search)){var v=f.Search.Trim();q=q.Where(x=>(x.CandidateProfile.User.FirstName+" "+x.CandidateProfile.User.LastName).Contains(v)||x.CandidateProfile.Headline!.Contains(v));}if(!string.IsNullOrWhiteSpace(f.ApplicationStatus)){if(!Enum.TryParse<ApplicationStatus>(f.ApplicationStatus,true,out var status))throw new ArgumentException("Invalid application status.");q=q.Where(x=>x.Status==status);}var rows=await q.Select(x=>new{ApplicationId=x.Id,CandidateId=x.CandidateProfileId,Name=x.CandidateProfile.User.FirstName+" "+x.CandidateProfile.User.LastName,x.CandidateProfile.Headline,x.Status,x.AppliedAt,Candidate=new CandidateData(x.CandidateProfileId,x.CandidateProfile.Headline,x.CandidateProfile.Summary,x.CandidateProfile.Education,x.CandidateProfile.Experience,x.CandidateProfile.Location,x.CandidateProfile.CandidateSkills.Select(s=>new SkillData(s.Skill.Name,true,s.YearsOfExperience)).ToList())}).ToListAsync(t);var ranked=rows.Select(x=>new{x.ApplicationId,x.CandidateId,x.Name,x.Headline,x.Status,x.AppliedAt,Match=Score(x.Candidate,job)}).Where(x=>!f.MinimumScore.HasValue||x.Match.MatchScore>=f.MinimumScore);ranked=f.Sort.ToLowerInvariant()switch{"newest"=>ranked.OrderByDescending(x=>x.AppliedAt),"name"=>ranked.OrderBy(x=>x.Name),_=>ranked.OrderByDescending(x=>x.Match.MatchScore).ThenByDescending(x=>x.Match.ConfidenceScore)};var list=ranked.ToList();return new(){Items=list.Skip((f.Page-1)*f.PageSize).Take(f.PageSize).Select(x=>new RankedCandidateDto(x.ApplicationId,x.CandidateId,x.Name,x.Headline,x.Status.ToString(),x.Match.MatchScore,x.Match.ConfidenceScore,x.Match.MatchedSkills,x.Match.MissingSkills,x.Match.Summary,x.AppliedAt)).ToList(),Page=f.Page,PageSize=f.PageSize,TotalItems=list.Count,TotalPages=(int)Math.Ceiling(list.Count/(double)f.PageSize)};
 }
 public async Task<JobMatchResultDto?>GetRecruiterApplicationMatchAsync(int recruiter,int app,CancellationToken t=default){var pair=await db.JobApplications.AsNoTracking().Where(x=>x.Id==app&&x.JobPosting.RecruiterProfile.UserId==recruiter).Select(x=>new{x.CandidateProfile.UserId,x.JobPostingId}).SingleOrDefaultAsync(t);return pair is null?null:await CalculateCandidateJobMatchAsync(pair.UserId,pair.JobPostingId,t);}
 public async Task<JobMatchResultDto?>GetManagerApplicationMatchAsync(int manager,int app,CancellationToken t=default){var pair=await db.JobApplications.AsNoTracking().Where(x=>x.Id==app&&db.HiringManagerProfiles.Any(m=>m.UserId==manager&&m.OrganizationId==x.JobPosting.OrganizationId&&(m.DepartmentId==null||m.DepartmentId==x.JobPosting.DepartmentId))).Select(x=>new{x.CandidateProfile.UserId,x.JobPostingId}).SingleOrDefaultAsync(t);return pair is null?null:await CalculateCandidateJobMatchAsync(pair.UserId,pair.JobPostingId,t);}
 async Task<CandidateData?>Candidate(int user,CancellationToken t)=>await db.CandidateProfiles.AsNoTracking().Where(x=>x.UserId==user).Select(x=>new CandidateData(x.Id,x.Headline,x.Summary,x.Education,x.Experience,x.Location,x.CandidateSkills.Select(s=>new SkillData(s.Skill.Name,true,s.YearsOfExperience)).ToList())).SingleOrDefaultAsync(t);
 async Task<JobData?>Job(int id,bool active,CancellationToken t){var now=DateTime.UtcNow;return await db.JobPostings.AsNoTracking().Where(x=>x.Id==id&&(!active||x.Status==JobStatus.Published&&(x.ClosingAt==null||x.ClosingAt>now)&&x.Organization.IsActive&&x.Department.IsActive)).Select(x=>new JobData(x.Id,x.Title,x.Description,x.Requirements,x.Location,x.WorkplaceType,x.EmploymentType,x.ExperienceLevel,x.Organization.Name,x.Department.Name,x.ClosingAt,x.JobSkills.Select(s=>new SkillData(s.Skill.Name,s.IsRequired,s.MinimumYearsOfExperience)).ToList())).SingleOrDefaultAsync(t);}
 static JobMatchResultDto Score(CandidateData c,JobData j)
 {
  var cs=c.Skills.GroupBy(x=>Norm(x.Name)).ToDictionary(x=>x.Key,x=>x.OrderByDescending(y=>y.Years??0).First());var js=j.Skills.GroupBy(x=>Norm(x.Name)).Select(x=>x.First()).ToList();var matched=js.Where(x=>cs.ContainsKey(Norm(x.Name))).Select(x=>x.Name).Distinct(StringComparer.OrdinalIgnoreCase).ToList();var missing=js.Where(x=>!cs.ContainsKey(Norm(x.Name))).Select(x=>x.Name).Distinct(StringComparer.OrdinalIgnoreCase).ToList();var additional=c.Skills.Where(x=>js.All(y=>Norm(y.Name)!=Norm(x.Name))).Select(x=>x.Name).Distinct(StringComparer.OrdinalIgnoreCase).ToList();double skillRatio;if(js.Count==0)skillRatio=.5;else{var req=js.Where(x=>x.Required).ToList();var pref=js.Where(x=>!x.Required).ToList();var rr=req.Count==0?1d:req.Count(x=>cs.ContainsKey(Norm(x.Name)))/(double)req.Count;var pr=pref.Count==0?1d:pref.Count(x=>cs.ContainsKey(Norm(x.Name)))/(double)pref.Count;skillRatio=req.Count>0&&pref.Count>0?rr*.8+pr*.2:req.Count>0?rr:pr;}var requiredYears=js.Where(x=>x.Years.HasValue).Select(x=>x.Years!.Value).DefaultIfEmpty().Max();var candidateYears=c.Skills.Where(x=>x.Years.HasValue).Select(x=>x.Years!.Value).DefaultIfEmpty().Max();var expRatio=requiredYears<=0?.5:(double)Math.Clamp(candidateYears/requiredYears,0,1);var eduKnown=!string.IsNullOrWhiteSpace(c.Education)&&!string.IsNullOrWhiteSpace(j.Requirements);var eduRatio=eduKnown?TokenOverlap(c.Education!,j.Requirements!):.5;var titleKnown=!string.IsNullOrWhiteSpace(c.Headline);var titleRatio=titleKnown?TokenOverlap(c.Headline!+" "+c.Summary,j.Title):.5;var remote=(j.WorkplaceType??"").Contains("remote",StringComparison.OrdinalIgnoreCase);var locationKnown=!string.IsNullOrWhiteSpace(c.Location);var locRatio=remote?1:locationKnown&&c.Location!.Contains(j.Location,StringComparison.OrdinalIgnoreCase)||locationKnown&&j.Location.Contains(c.Location!,StringComparison.OrdinalIgnoreCase)?1:locationKnown?0:.5;const double employmentRatio=.5;var parts=new[]{(int)Math.Round(skillRatio*45),(int)Math.Round(expRatio*20),(int)Math.Round(eduRatio*10),(int)Math.Round(titleRatio*10),(int)Math.Round(locRatio*10),(int)Math.Round(employmentRatio*5)};var score=Math.Clamp(parts.Sum(),0,100);var confidence=Math.Clamp((js.Count>0?30:0)+(c.Skills.Count>0?20:0)+(requiredYears>0&&candidateYears>0?15:0)+(eduKnown?10:0)+(titleKnown?10:0)+(locationKnown||remote?10:0)+5,0,100);var strengths=new List<string>();var gaps=new List<string>();if(js.Count>0)strengths.Add($"Matches {matched.Count} of {js.Count} listed skills");else gaps.Add("The job has no structured skills for comparison");if(expRatio>=.75)strengths.Add("Structured experience is close to or above the requirement");else if(requiredYears>0)gaps.Add("Structured experience is below the listed requirement");if(remote||locRatio==1)strengths.Add(remote?"Remote work avoids a location mismatch":"Candidate and job locations align");if(missing.Count>0)gaps.Add($"{missing.Count} listed skill{(missing.Count==1?" is":"s are")} missing");if(!eduKnown)gaps.Add("Education matching data is incomplete");if(!titleKnown)gaps.Add("Professional title is not provided");var summary=score>=80?"Strong alignment with the available job requirements.":score>=60?"Good alignment with some development areas.":score>=40?"Partial alignment based on available profile data.":"Limited alignment based on available profile data.";return new(score,confidence,matched,missing,additional,strengths,gaps,new(parts[0],parts[1],parts[2],parts[3],parts[4],parts[5]),summary);
 }
 static string Norm(string value){var x=Regex.Replace(value.Trim().ToLowerInvariant(),@"[^a-z0-9+#.]+"," ").Trim();return Aliases.TryGetValue(x,out var alias)?alias:x;}
 static double TokenOverlap(string a,string b){var aa=Regex.Matches(a.ToLowerInvariant(),@"[a-z0-9+#.]+").Select(x=>x.Value).Where(x=>!Stop.Contains(x)).ToHashSet();var bb=Regex.Matches(b.ToLowerInvariant(),@"[a-z0-9+#.]+").Select(x=>x.Value).Where(x=>!Stop.Contains(x)).ToHashSet();return aa.Count==0||bb.Count==0?.5:aa.Intersect(bb).Count()/(double)Math.Min(aa.Count,bb.Count);}
}
